1	/**
2	 * @module features/tv-dashboard/model/tvMath
3	 *
4	 * Funções PURAS do Dashboard de Crise (painel TV): pró-rata de meta,
5	 * delta semanal, classificação RAG, formatação compacta de moeda,
6	 * staleness e agregações determinísticas usadas pelo hook de dados.
7	 *
8	 * Tudo aqui é livre de I/O e testável em isolamento (`tvMath.test.ts`).
9	 */
10	
11	import type {
12	  TvBusinessHours,
13	  TvCriticalItem,
14	  TvDateRange,
15	  TvException,
16	  TvExceptionsResult,
17	  TvFreshness,
18	  TvFreshnessLevel,
19	  TvPeriod,
20	  TvRagStatus,
21	  TvRecentMove,
22	  TvStockAlertItem,
23	  TvStoreWeeklyGoal,
24	  TvWeekSegment,
25	  TvWeeklyGoal,
26	} from './types';
27	
28	// ─────────────────────────────────────────────────────────────────────────────
29	// Constantes de negócio
30	// ─────────────────────────────────────────────────────────────────────────────
31	
32	/**
33	 * Janela de funcionamento das LOJAS usada no pró-rata da meta (hora local,
34	 * design.md §1.6 regra 5: 10:00–22:00). AJUSTÁVEL: se o horário comercial
35	 * mudar, basta alterar aqui — pró-rata e "sem movimentação" derivam daqui.
36	 */
37	export const TV_BUSINESS_HOURS: TvBusinessHours = { start: 10, end: 22 };
38	
39	/**
40	 * Janela de produção da FÁBRICA (design.md §1.6 regra 5 + §5: 06:00–18:00).
41	 * Usada TANTO no RAG da fábrica quanto no alerta visual do card.
42	 */
43	export const TV_FACTORY_HOURS: TvBusinessHours = { start: 6, end: 18 };
44	
45	/** Horas sem movimentação (dentro da janela) que tornam a LOJA âmbar. */
46	export const NO_MOVEMENT_THRESHOLD_HOURS = 3;
47	
48	/** Horas sem bipagem (na janela de produção) que tornam a FÁBRICA âmbar (§5). */
49	export const FACTORY_NO_MOVEMENT_THRESHOLD_HOURS = 2;
50	
51	/**
52	 * Ratio pró-rata (%real / %esperado, em %) abaixo do qual a venda live fica
53	 * ÂMBAR — nunca vermelho (design.md §1.6 regra 6: ratio menor que 0,75).
54	 */
55	export const LIVE_SALES_AMBER_THRESHOLD_PCT = 75;
56	
57	/** Hora local a partir da qual a regra de venda fraca passa a valer (§1.6). */
58	export const LIVE_SALES_AMBER_FROM_HOUR = 11;
59	
60	/** Máximo de linhas exibidas na faixa de exceções. */
61	export const TV_EXCEPTIONS_LIMIT = 7;
62	
63	/** Itens do mini-feed "AGORA" por coluna de unidade. */
64	export const TV_MINI_FEED_SIZE = 3;
65	
66	/** Itens de estoque crítico exibidos na coluna (lista completa no drill-down). */
67	export const TV_CRITICAL_TOP_N = 5;
68	
69	/** Máximo de linhas do feed de movimentações no drill-down por loja. */
70	export const TV_DETAIL_FEED_LIMIT = 50;
71	
72	/**
73	 * Setor canônico de `produtos_master.setor` cujos itens entram nos ALERTAS
74	 * de estoque crítico do painel (regra do CTO 2026-06-05: alertas só do setor
75	 * de produtos vendáveis — EMBALAGENS, INSUMOS, CÂMARA FRIA, ITENS COZINHA,
76	 * MERCEARIA, COMIDAS, PRODUTOS DE LIMPEZA etc. ficam FORA).
77	 *
78	 * Comparar SEMPRE por igualdade exata pós-{@link normalizeSetor} (nunca por
79	 * prefixo/ILIKE: existe o setor "PRODUTOS DE LIMPEZA") — use
80	 * {@link isTvAlertSetor}.
81	 */
82	export const TV_ALERT_SETOR = 'PRODUTOS';
83	
84	/**
85	 * ÚNICA loja cujo faturamento de PDV embute delivery (BSB Shopping): lá o
86	 * iFood/delivery passa pelo caixa Degust junto com o balcão, então o card
87	 * quebra "Loja × Delivery" (R1 da spec tv-acompanhamento-live). Nas demais
88	 * lojas o delivery NÃO entra no PDV — quebra não se aplica.
89	 *
90	 * É `lojas.id` interno (não código Degust). Constante nomeada de propósito:
91	 * exceção de NEGÓCIO documentada, não um hardcode espalhado.
92	 */
93	export const TV_DELIVERY_SPLIT_LOJA_ID = 6;
94	
95	// ─────────────────────────────────────────────────────────────────────────────
96	// Datas (helpers locais, sem dependência de timezone UTC)
97	// ─────────────────────────────────────────────────────────────────────────────
98	
99	/** Formata uma data como YYYY-MM-DD no fuso LOCAL (não UTC). */
100	export function toIsoDateLocal(d: Date): string {
101	  const y = d.getFullYear();
102	  const m = String(d.getMonth() + 1).padStart(2, '0');
103	  const day = String(d.getDate()).padStart(2, '0');
104	  return `${y}-${m}-${day}`;
105	}
106	
107	/** Faz parse de YYYY-MM-DD como data LOCAL (evita shift de fuso do `new Date(iso)`). */
108	export function parseIsoDateLocal(iso: string): Date {
109	  const [y, m, d] = iso.split('-').map(Number);
110	  return new Date(y, (m ?? 1) - 1, d ?? 1);
111	}
112	
113	/** Soma `days` dias a uma data, retornando nova instância. */
114	export function addDays(d: Date, days: number): Date {
115	  const out = new Date(d);
116	  out.setDate(out.getDate() + days);
117	  return out;
118	}
119	
120	/** Rótulo de defasagem "até DD/MM" para dado que não é de hoje. */
121	export function formatLaggedDateLabel(isoDate: string): string {
122	  const d = parseIsoDateLocal(isoDate);
123	  const dd = String(d.getDate()).padStart(2, '0');
124	  const mm = String(d.getMonth() + 1).padStart(2, '0');
125	  return `até ${dd}/${mm}`;
126	}
127	
128	/**
129	 * Parser do timestamp pt-BR do Degust (`ultima_atualizacao` vem como
130	 * "DD/MM/YYYY HH:mm:ss"): `new Date()` interpreta como MM/DD e FALHA para
131	 * dia maior que 12. Faz parse como data LOCAL; aceita segundos opcionais e
132	 * cai pro parse nativo para outros formatos (ex.: ISO). Inválido → null.
133	 */
134	export function parseBrDateTime(value: string | null | undefined): Date | null {
135	  if (!value) return null;
136	  const m = value.match(
137	    /^(\d{2})\/(\d{2})\/(\d{4})[ T](\d{2}):(\d{2})(?::(\d{2}))?$/,
138	  );
139	  if (m) {
140	    const [, dd, mm, yyyy, hh, mi, ss] = m;
141	    const month = Number(mm);
142	    const day = Number(dd);
143	    if (month < 1 || month > 12 || day < 1 || day > 31) return null;
144	    return new Date(
145	      Number(yyyy),
146	      month - 1,
147	      day,
148	      Number(hh),
149	      Number(mi),
150	      ss ? Number(ss) : 0,
151	    );
152	  }
153	  const fallback = new Date(value);
154	  return Number.isNaN(fallback.getTime()) ? null : fallback;
155	}
156	
157	/** Hora local "HH:mm" de um timestamp ISO ("—" para ausente/inválido). */
158	export function timeHHMMFromIso(iso: string | null | undefined): string {
159	  if (!iso) return '—';
160	  const d = new Date(iso);
161	  if (Number.isNaN(d.getTime())) return '—';
162	  const hh = String(d.getHours()).padStart(2, '0');
163	  const mm = String(d.getMinutes()).padStart(2, '0');
164	  return `${hh}:${mm}`;
165	}
166	
167	// ─────────────────────────────────────────────────────────────────────────────
168	// Ranges do filtro global de período (v3) — datas LOCAIS, puras e testáveis
169	// ─────────────────────────────────────────────────────────────────────────────
170	
171	/**
172	 * Range do filtro global (fechado [from, to], YYYY-MM-DD local):
173	 * - `today`: hoje → hoje;
174	 * - `week`: segunda-feira da semana corrente → hoje;
175	 * - `month`: dia 1º do mês corrente → hoje.
176	 */
177	export function periodRange(period: TvPeriod, now: Date): TvDateRange {
178	  const today = toIsoDateLocal(now);
179	  if (period === 'today') return { from: today, to: today };
180	  if (period === 'week') {
181	    // getDay(): 0=domingo → 0=segunda com (dow+6)%7
182	    const dowFromMonday = (now.getDay() + 6) % 7;
183	    const monday = addDays(now, -dowFromMonday);
184	    return { from: toIsoDateLocal(monday), to: today };
185	  }
186	  const firstOfMonth = new Date(now.getFullYear(), now.getMonth(), 1);
187	  return { from: toIsoDateLocal(firstOfMonth), to: today };
188	}
189	
190	/**
191	 * Período ANTERIOR equivalente para comparativos do filtro global:
192	 * - `today`: ontem → ontem;
193	 * - `week`: semana passada até o MESMO dia da semana (seg → hoje−7);
194	 * - `month`: mês passado do dia 1º até o MESMO dia do mês — clampado ao
195	 *   último dia quando o mês anterior é mais curto (31/05 → 30/04).
196	 */
197	export function previousPeriodRange(period: TvPeriod, now: Date): TvDateRange {
198	  if (period === 'today') {
199	    const yesterday = toIsoDateLocal(addDays(now, -1));
200	    return { from: yesterday, to: yesterday };
201	  }
202	  if (period === 'week') {
203	    const dowFromMonday = (now.getDay() + 6) % 7;
204	    const mondayLastWeek = addDays(now, -dowFromMonday - 7);
205	    return {
206	      from: toIsoDateLocal(mondayLastWeek),
207	      to: toIsoDateLocal(addDays(now, -7)),
208	    };
209	  }
210	  const y = now.getFullYear();
211	  const m = now.getMonth();
212	  const firstPrev = new Date(y, m - 1, 1);
213	  // `new Date(y, m, 0)` = último dia do mês ANTERIOR a `m`
214	  const lastDayPrevMonth = new Date(y, m, 0).getDate();
215	  const toPrev = new Date(y, m - 1, Math.min(now.getDate(), lastDayPrevMonth));
216	  return { from: toIsoDateLocal(firstPrev), to: toIsoDateLocal(toPrev) };
217	}
218	
219	/**
220	 * Range anterior de MESMA DURAÇÃO em dias, imediatamente antes do range
221	 * dado (drill-down com filtro custom: [from−N, from−1] para N dias).
222	 */
223	export function previousRangeSameDuration(range: TvDateRange): TvDateRange {
224	  const from = parseIsoDateLocal(range.from);
225	  const to = parseIsoDateLocal(range.to);
226	  // Math.round absorve a hora de DST (diferença 23h/25h em viradas de horário)
227	  const days = Math.round((to.getTime() - from.getTime()) / 86_400_000) + 1;
228	  return {
229	    from: toIsoDateLocal(addDays(from, -days)),
230	    to: toIsoDateLocal(addDays(to, -days)),
231	  };
232	}
233	
234	/**
235	 * Converte um range de DIAS locais em limites de TIMESTAMP para filtrar
236	 * colunas timestamptz (ex.: `perdas.data_identificacao`): início = 00:00
237	 * local do 1º dia (inclusive); fim = 00:00 local do dia SEGUINTE ao último
238	 * (exclusivo — usar `.lt`, nunca `.lte`).
239	 */
240	export function rangeToLocalDayBounds(range: TvDateRange): {
241	  startIso: string;
242	  endExclusiveIso: string;
243	} {
244	  const start = parseIsoDateLocal(range.from);
245	  const endExclusive = addDays(parseIsoDateLocal(range.to), 1);
246	  return {
247	    startIso: start.toISOString(),
248	    endExclusiveIso: endExclusive.toISOString(),
249	  };
250	}
251	
252	/**
253	 * Range do filtro global DESLOCADO `offset` períodos no tempo (R2 —
254	 * histórico navegável). Offset 0 = comportamento de {@link periodRange}
255	 * (período corrente, parcial até hoje). Offset −n = período PASSADO
256	 * COMPLETO n posições atrás:
257	 * - `today`: o dia inteiro n dias atrás;
258	 * - `week`: a semana seg-dom COMPLETA n semanas atrás;
259	 * - `month`: o mês-calendário COMPLETO n meses atrás.
260	 *
261	 * Offset positivo não é suportado (não há futuro a navegar) — tratado
262	 * como 0 por segurança.
263	 */
264	export function shiftedPeriodRange(
265	  period: TvPeriod,
266	  offset: number,
267	  now: Date,
268	): TvDateRange {
269	  if (offset >= 0) return periodRange(period, now);
270	  if (period === 'today') {
271	    const day = toIsoDateLocal(addDays(now, offset));
272	    return { from: day, to: day };
273	  }
274	  if (period === 'week') {
275	    const dowFromMonday = (now.getDay() + 6) % 7;
276	    const monday = addDays(now, -dowFromMonday + offset * 7);
277	    return { from: toIsoDateLocal(monday), to: toIsoDateLocal(addDays(monday, 6)) };
278	  }
279	  const first = new Date(now.getFullYear(), now.getMonth() + offset, 1);
280	  // `new Date(y, m+1, 0)` = último dia do mês `m`
281	  const last = new Date(now.getFullYear(), now.getMonth() + offset + 1, 0);
282	  return { from: toIsoDateLocal(first), to: toIsoDateLocal(last) };
283	}
284	
285	// ─────────────────────────────────────────────────────────────────────────────
286	// Meta mensal — semanas seg-dom recortadas ao mês + redistribuição (R4)
287	// ─────────────────────────────────────────────────────────────────────────────
288	
289	/**
290	 * Segmentos seg-dom de um mês, RECORTADOS aos limites do mês: o primeiro
291	 * e o último podem ter menos de 7 dias (mês que começa/termina no meio da
292	 * semana). `index` é 1-based ("Semana 1").
293	 *
294	 * @param year - Ano (ex.: 2026).
295	 * @param monthIndex0 - Mês 0-based (convenção JS `Date.getMonth()`).
296	 */
297	export function monthWeekSegments(
298	  year: number,
299	  monthIndex0: number,
300	): TvWeekSegment[] {
301	  const lastDay = new Date(year, monthIndex0 + 1, 0).getDate();
302	  const segments: TvWeekSegment[] = [];
303	  let day = 1;
304	  let index = 1;
305	  while (day <= lastDay) {
306	    const start = new Date(year, monthIndex0, day);
307	    const dowFromMonday = (start.getDay() + 6) % 7;
308	    const endDay = Math.min(day + (6 - dowFromMonday), lastDay);
309	    segments.push({
310	      index,
311	      from: toIsoDateLocal(start),
312	      to: toIsoDateLocal(new Date(year, monthIndex0, endDay)),
313	      days: endDay - day + 1,
314	    });
315	    day = endDay + 1;
316	    index += 1;
317	  }
318	  return segments;
319	}
320	
321	/**
322	 * Metas semanais do mês de `now` com REDISTRIBUIÇÃO iterativa da meta
323	 * mensal (que é fixa): para cada segmento, em ordem,
324	 * `target = (metaMensal − comprometido) × dias do segmento ÷ dias restantes`,
325	 * onde "comprometido" acumula o REALIZADO das semanas já encerradas e o
326	 * TARGET das semanas correntes/futuras (assume on-target dali em diante).
327	 *
328	 * Consequências (A4 da spec):
329	 * - semana que não bate a meta ⇒ targets das seguintes SOBEM;
330	 * - semana que supera ⇒ targets das seguintes DESCEM;
331	 * - invariante: realizado das semanas passadas + soma dos targets
332	 *   restantes = metaMensal, sempre (targets podem ficar negativos se o
333	 *   realizado já passou da meta — honesto, sem clamp).
334	 *
335	 * `achieved` = soma de `realizadoPorDia` nos dias do segmento (semanas
336	 * passadas e corrente); null para semanas futuras (sem dados ainda).
337	 */
338	export function weeklyTargets(
339	  metaMensal: number,
340	  realizadoPorDia: Map<string, number>,
341	  now: Date,
342	): TvWeeklyGoal[] {
343	  const segments = monthWeekSegments(now.getFullYear(), now.getMonth());
344	  const todayIso = toIsoDateLocal(now);
345	  const sumSegment = (seg: TvWeekSegment): number => {
346	    let sum = 0;
347	    let d = parseIsoDateLocal(seg.from);
348	    for (let i = 0; i < seg.days; i += 1) {
349	      sum += realizadoPorDia.get(toIsoDateLocal(d)) ?? 0;
350	      d = addDays(d, 1);
351	    }
352	    return sum;
353	  };
354	
355	  let committed = 0;
356	  let daysRemaining = segments.reduce((s, seg) => s + seg.days, 0);
357	  const out: TvWeeklyGoal[] = [];
358	  for (const seg of segments) {
359	    const target =
360	      daysRemaining > 0 ? ((metaMensal - committed) * seg.days) / daysRemaining : 0;
361	    const isPast = seg.to < todayIso;
362	    const isCurrent = seg.from <= todayIso && todayIso <= seg.to;
363	    const achieved = isPast || isCurrent ? sumSegment(seg) : null;
364	    out.push({ segment: seg, target, achieved, isCurrent });
365	    // Passadas comprometem o REAL (déficit/superávit redistribui);
366	    // corrente/futuras comprometem o TARGET (projeção on-target).
367	    committed += isPast ? (achieved ?? 0) : target;
368	    daysRemaining -= seg.days;
369	  }
370	  return out;
371	}
372	
373	/**
374	 * Meta semanal de UMA loja na SEMANA CORRENTE: aplica {@link weeklyTargets}
375	 * (mesma redistribuição da meta mensal usada no monthProgress da rede) ao
376	 * realizado diário da loja e extrai o segmento corrente.
377	 *
378	 * - `target` = meta redistribuída da semana corrente (semana 1 abaixo da
379	 *   meta ⇒ target sobe; acima ⇒ desce);
380	 * - `achieved` = soma do realizado nos dias do segmento corrente (segunda →
381	 *   agora — dias futuros não têm entrada no mapa e contam 0);
382	 * - `pct` = achieved/target × 100, null se target ≤ 0 (sem % honesto).
383	 *
384	 * Retorna null quando não há meta mensal positiva cadastrada ou quando
385	 * `now` está fora de qualquer segmento do mês (não acontece na prática).
386	 */
387	export function currentWeekGoal(
388	  metaMensal: number | null | undefined,
389	  realizadoPorDia: Map<string, number>,
390	  now: Date,
391	): TvStoreWeeklyGoal | null {
392	  if (metaMensal == null || metaMensal <= 0) return null;
393	  const current = weeklyTargets(metaMensal, realizadoPorDia, now).find(
394	    (w) => w.isCurrent,
395	  );
396	  if (!current) return null;
397	  const achieved = current.achieved ?? 0;
398	  return {
399	    target: current.target,
400	    achieved,
401	    pct: current.target > 0 ? (achieved / current.target) * 100 : null,
402	  };
403	}
404	
405	/**
406	 * Fração ESPERADA da semana corrente já decorrida em `now` — análoga ao
407	 * `expectedMonthPct` da barra mensal (dias inteiros; HOJE conta inteiro,
408	 * mesmo padrão de `now.getDate() / daysInMonth`). A "semana" é o segmento
409	 * seg-dom do mês CORRENTE recortado por {@link monthWeekSegments} (mesmo
410	 * recorte de {@link weeklyTargets}/{@link currentWeekGoal}).
411	 *
412	 * Uso: pace-ajustar a COR da meta semanal (`ratio = %real / %esperado`),
413	 * consistente com a barra mensal — começo de semana no ritmo NÃO fica
414	 * vermelho. O % numérico exibido segue sendo o real (achieved/target).
415	 *
416	 * Retorna 1 se `now` não cair em nenhum segmento (defensivo — na prática
417	 * todo dia do mês pertence a um segmento).
418	 */
419	export function expectedWeekFraction(now: Date): number {
420	  const todayIso = toIsoDateLocal(now);
421	  const segment = monthWeekSegments(now.getFullYear(), now.getMonth()).find(
422	    (s) => s.from <= todayIso && todayIso <= s.to,
423	  );
424	  if (!segment) return 1;
425	  // Math.round absorve a hora de DST (diferença 23h/25h em viradas)
426	  const elapsedDays =
427	    Math.round(
428	      (parseIsoDateLocal(todayIso).getTime() -
429	        parseIsoDateLocal(segment.from).getTime()) /
430	        86_400_000,
431	    ) + 1;
432	  return Math.min(1, elapsedDays / segment.days);
433	}
434	
435	// ─────────────────────────────────────────────────────────────────────────────
436	// Curva horária (R5) + projeção de fim de mês (R3)
437	// ─────────────────────────────────────────────────────────────────────────────
438	
439	/**
440	 * Hora-limite da madrugada no DIA COMERCIAL: buckets 00h–05h pertencem ao
441	 * FIM do dia, não ao começo. O caixa do Degust agrupa por dataCaixa — uma
442	 * venda às 02:00 tem dataCaixa do dia anterior (é o fechamento da noite),
443	 * então na curva horária ela vem DEPOIS das 23h, nunca antes da manhã.
444	 *
445	 * NÃO usar {@link TV_BUSINESS_HOURS}.start (10h) como corte: a loja Lago
446	 * Sul é brunch e vende legitimamente às 08h–09h (byHour real com chaves
447	 * "08"/"09"). Lojas abrem no mínimo às 8h — 06h é um corte seguro.
448	 */
449	export const TV_OVERNIGHT_END_HOUR = 6;
450	
451	/**
452	 * Rank de uma hora-calendário dentro do DIA COMERCIAL: madrugada (00–05)
453	 * desloca +24 para ordenar DEPOIS das 23h. Sequência resultante:
454	 * 06, 07, …, 23, 24 (=00h), 25 (=01h), …, 29 (=05h).
455	 */
456	export function businessHourRank(hour: number): number {
457	  return hour < TV_OVERNIGHT_END_HOUR ? hour + 24 : hour;
458	}
459	
460	/**
461	 * Base "ontem até a MESMA hora" usando a curva horária REAL do dia de
462	 * referência: `prevDayTotal` × fração, onde fração = cumulativo de
463	 * `prevDayByHour` até HH:mm ÷ cumulativo total. A hora corrente entra com
464	 * fração linear do minuto dentro da hora (15:30 → metade do bucket "15").
465	 *
466	 * A curva é usada APENAS como fração (kits têm valorUnitario 0 na fonte) —
467	 * o valor absoluto vem sempre do total oficial `prevDayTotal`.
468	 *
469	 * O cumulativo segue a ordem do DIA COMERCIAL ({@link businessHourRank}):
470	 * buckets da madrugada (00h–05h, dataCaixa do dia anterior — fechamento da
471	 * noite) ordenam DEPOIS das 23h, e a hora corrente também é ranqueada —
472	 * às 00:30 o ponto de corte é 24,5 (fim do dia comercial corrente), não
473	 * 0,5. Sem isso, uma venda às 02h de ontem inflava a base da MANHÃ de hoje.
474	 *
475	 * Retorna null quando não há base honesta — curva ausente/vazia, cumulativo
476	 * total 0, total não positivo ou fração 0 (antes da 1ª venda do dia de
477	 * referência) — para o caller cair no fallback pró-rata linear existente.
478	 */
479	export function hourlyPaceBase(
480	  prevDayTotal: number,
481	  prevDayByHour: Record<string, number> | undefined,
482	  now: Date,
483	): number | null {
484	  if (prevDayTotal <= 0 || !prevDayByHour) return null;
485	  const buckets: Array<[number, number]> = [];
486	  for (const [hh, value] of Object.entries(prevDayByHour)) {
487	    const hour = Number(hh);
488	    if (!Number.isInteger(hour) || hour < 0 || hour > 23) continue;
489	    buckets.push([businessHourRank(hour), value]);
490	  }
491	  const cumTotal = buckets.reduce((s, [, v]) => s + v, 0);
492	  if (cumTotal <= 0) return null;
493	  const currentRank = businessHourRank(now.getHours());
494	  const minuteFraction = (now.getMinutes() + now.getSeconds() / 60) / 60;
495	  let cumNow = 0;
496	  for (const [rank, value] of buckets) {
497	    if (rank < currentRank) cumNow += value;
498	    else if (rank === currentRank) cumNow += value * minuteFraction;
499	  }
500	  if (cumNow <= 0) return null;
501	  return prevDayTotal * (cumNow / cumTotal);
502	}
503	
504	/**
505	 * Projeção de fim de mês por run-rate (mtd ÷ dias decorridos × dias do
506	 * mês), com "dias decorridos" = dias COMPLETOS decorridos + 1 (hoje conta
507	 * inteiro — sem fração de dia, decisão da spec). No dia 1º a projeção é
508	 * o run-rate de 1 dia (`mtd × diasDoMês`).
509	 */
510	export function monthEndProjection(mtdTotal: number, now: Date): number {
511	  const daysInMonth = new Date(now.getFullYear(), now.getMonth() + 1, 0).getDate();
512	  const daysElapsed = now.getDate();
513	  return (mtdTotal / daysElapsed) * daysInMonth;
514	}
