516	// ─────────────────────────────────────────────────────────────────────────────
517	// Pró-rata da meta
518	// ─────────────────────────────────────────────────────────────────────────────
519	
520	/**
521	 * Fração linear do dia comercial já decorrida em `now`.
522	 *
523	 * - Antes da abertura → 0 (não há venda esperada ainda).
524	 * - Depois do fechamento → 1 (meta integral esperada).
525	 * - Dentro da janela → interpolação linear simples (pró-rata).
526	 */
527	export function businessDayFraction(
528	  now: Date,
529	  hours: TvBusinessHours = TV_BUSINESS_HOURS,
530	): number {
531	  const { start, end } = hours;
532	  if (end <= start) {
533	    // Janela inválida — fail fast com comportamento seguro (sem divisão por 0)
534	    return now.getHours() >= end ? 1 : 0;
535	  }
536	  const h = now.getHours() + now.getMinutes() / 60 + now.getSeconds() / 3600;
537	  if (h <= start) return 0;
538	  if (h >= end) return 1;
539	  return (h - start) / (end - start);
540	}
541	
542	/**
543	 * % da meta pró-rata: vendido / (meta diária × fração da janela decorrida).
544	 *
545	 * Retorna null quando não dá para calcular com honestidade:
546	 * - meta ausente/zerada (sem referência), ou
547	 * - antes da janela de funcionamento (esperado = 0; divisão sem sentido).
548	 */
549	export function pctOfProRataTarget(
550	  sold: number,
551	  dailyTarget: number | null | undefined,
552	  now: Date,
553	  hours: TvBusinessHours = TV_BUSINESS_HOURS,
554	): number | null {
555	  if (dailyTarget == null || dailyTarget <= 0) return null;
556	  const fraction = businessDayFraction(now, hours);
557	  if (fraction <= 0) return null;
558	  return (sold / (dailyTarget * fraction)) * 100;
559	}
560	
561	/**
562	 * % da meta de um dia COMPLETO (sem pró-rata) — usado para canal defasado,
563	 * cujo dia de referência já encerrou.
564	 */
565	export function pctOfFullDayTarget(
566	  sold: number,
567	  dailyTarget: number | null | undefined,
568	): number | null {
569	  if (dailyTarget == null || dailyTarget <= 0) return null;
570	  return (sold / dailyTarget) * 100;
571	}
