573	// ─────────────────────────────────────────────────────────────────────────────
574	// Deltas comparativos (genéricos: vendas, perdas, compras — qualquer base)
575	// ─────────────────────────────────────────────────────────────────────────────
576	
577	/**
578	 * Delta % de `current` vs uma base de referência qualquer (ontem, semana
579	 * passada, período anterior do filtro…). Retorna null quando a base é
580	 * ausente ou não positiva — sem base honesta, sem número inventado.
581	 */
582	export function relativeDelta(
583	  current: number,
584	  base: number | null | undefined,
585	): number | null {
586	  if (base == null || base <= 0) return null;
587	  return ((current - base) / base) * 100;
588	}
589	
590	/**
591	 * Delta % vs MESMO DIA da semana anterior — caso particular de
592	 * {@link relativeDelta}, mantido pelo nome de domínio (comparativo
593	 * SECUNDÁRIO desde a v3; o principal é vs dia anterior).
594	 */
595	export function weekOverWeekDelta(
596	  current: number,
597	  lastWeek: number | null | undefined,
598	): number | null {
599	  return relativeDelta(current, lastWeek);
600	}
601	
602	/**
603	 * Base PRÓ-RATEADA de QUALQUER dia de referência para deltas do canal LIVE:
604	 * `referenceDayTotal × businessDayFraction(now)` — o delta resultante compara
605	 * hoje (dia parcial) vs o MESMO PONTO do dia de referência (ontem, semana
606	 * passada…), assumindo distribuição intra-dia linear na janela (mesma fração
607	 * usada no pró-rata da meta, por consistência).
608	 *
609	 * Comparar dia parcial com dia completo inflava a queda de manhã.
610	 * Canal defasado (dia completo vs dia completo) NÃO usa esta função.
611	 *
612	 * Retorna null quando a base é ausente/não positiva ou antes da abertura
613	 * (fração 0 — não há ponto de comparação honesto).
614	 */
615	export function proRataDayBase(
616	  referenceDayTotal: number | null | undefined,
617	  now: Date,
618	  hours: TvBusinessHours = TV_BUSINESS_HOURS,
619	): number | null {
620	  if (referenceDayTotal == null || referenceDayTotal <= 0) return null;
621	  const fraction = businessDayFraction(now, hours);
622	  if (fraction <= 0) return null;
623	  return referenceDayTotal * fraction;
624	}
625	
626	/**
627	 * Alias histórico de {@link proRataDayBase} com o dia de referência fixado
628	 * em "mesmo dia da semana passada" (nome da v1/v2 — mantido para não quebrar
629	 * a API existente).
630	 */
631	export function proRataLastWeekBase(
632	  lastWeek: number | null | undefined,
633	  now: Date,
634	  hours: TvBusinessHours = TV_BUSINESS_HOURS,
635	): number | null {
636	  return proRataDayBase(lastWeek, now, hours);
637	}
