642	
643	/** Entrada da classificação RAG de uma unidade. */
644	export interface StoreRagInput {
645	  /** Itens zerados em alerta (quantidade ≤ 0 com mínimo definido). */
646	  stockOutCount: number;
647	  /** Itens abaixo do mínimo (quantidade entre 0 exclusivo e o mínimo). */
648	  stockLowCount: number;
649	  /** % da meta pró-rata (apenas canal live; null = não avaliar). */
650	  pctMetaProRata: number | null;
651	  /** true quando a unidade tem venda ao vivo (canal Degust). */
652	  isLiveChannel: boolean;
653	  /** Última movimentação de estoque (ISO/Date), ou null se nenhuma hoje. */
654	  lastMovementAt: Date | string | null;
655	  /** Instante da avaliação. */
656	  now: Date;
657	  /** Janela de funcionamento (default lojas; fábrica usa TV_FACTORY_HOURS). */
658	  hours?: TvBusinessHours;
659	  /** Threshold de horas sem movimentação (default lojas 3h; fábrica 2h). */
660	  noMovementThresholdHours?: number;
661	}
662	
663	/**
664	 * Horas sem movimentação consideradas DENTRO da janela de funcionamento.
665	 *
666	 * - Fora da janela (antes de abrir / depois de fechar) retorna null —
667	 *   não faz sentido alertar madrugada sem bipagem.
668	 * - A referência é clampada ao início da janela de hoje: se a última
669	 *   movimentação foi ontem, o "relógio" só começa a contar na abertura.
670	 */
671	export function hoursWithoutMovementInWindow(
672	  lastMovementAt: Date | string | null,
673	  now: Date,
674	  hours: TvBusinessHours = TV_BUSINESS_HOURS,
675	): number | null {
676	  const fraction = businessDayFraction(now, hours);
677	  if (fraction <= 0 || fraction >= 1) return null;
678	  const windowStart = new Date(now);
679	  windowStart.setHours(hours.start, 0, 0, 0);
680	  const last = lastMovementAt
681	    ? new Date(lastMovementAt).getTime()
682	    : Number.NEGATIVE_INFINITY;
683	  const ref = Math.max(last, windowStart.getTime());
684	  return (now.getTime() - ref) / 3_600_000;
685	}
686	
687	/**
688	 * Classificação RAG de uma unidade (management-by-exception).
689	 *
690	 * Regras (design.md §1.6, ordem de precedência):
691	 * - VERMELHO: SOMENTE ruptura — item zerado em alerta (`stockOutCount > 0`).
692	 *   Venda fraca NUNCA derruba o card pra vermelho (era falso-positivo de
693	 *   manhã, quando o pró-rata ainda é instável).
694	 * - ÂMBAR: itens abaixo do mínimo (`stockLowCount > 0`) OU unidade sem
695	 *   movimentação há mais que o threshold dentro da janela OU venda live com
696	 *   ratio pró-rata abaixo de {@link LIVE_SALES_AMBER_THRESHOLD_PCT}% —
697	 *   esta última SOMENTE a partir de {@link LIVE_SALES_AMBER_FROM_HOUR}h,
698	 *   em canal live e com meta cadastrada (pct != null).
699	 * - OK: nenhum desvio — tela calma, sem cor.
700	 */
701	export function classifyStoreRag(input: StoreRagInput): {
702	  status: TvRagStatus;
703	  reasons: string[];
704	} {
705	  const hours = input.hours ?? TV_BUSINESS_HOURS;
706	  const noMovementThreshold =
707	    input.noMovementThresholdHours ?? NO_MOVEMENT_THRESHOLD_HOURS;
708	  const reasons: string[] = [];
709	
710	  // ── Vermelho: só ruptura (item zerado em alerta) ──
711	  if (input.stockOutCount > 0) {
712	    reasons.push(
713	      `${input.stockOutCount} ${input.stockOutCount === 1 ? 'item zerado' : 'itens zerados'} em alerta`,
714	    );
715	    return { status: 'red', reasons };
716	  }
717	
718	  // ── Âmbar ──
719	  if (input.stockLowCount > 0) {
720	    reasons.push(
721	      `${input.stockLowCount} ${input.stockLowCount === 1 ? 'item abaixo' : 'itens abaixo'} do mínimo`,
722	    );
723	  }
724	  const gapHours = hoursWithoutMovementInWindow(
725	    input.lastMovementAt,
726	    input.now,
727	    hours,
728	  );
729	  if (gapHours !== null && gapHours > noMovementThreshold) {
730	    reasons.push(`sem movimentação há ${Math.floor(gapHours)}h`);
731	  }
732	  if (
733	    input.isLiveChannel &&
734	    input.pctMetaProRata !== null &&
735	    input.pctMetaProRata < LIVE_SALES_AMBER_THRESHOLD_PCT &&
736	    input.now.getHours() >= LIVE_SALES_AMBER_FROM_HOUR
737	  ) {
738	    reasons.push(
739	      `venda ao vivo em ${Math.round(input.pctMetaProRata)}% do esperado pró-rata`,
740	    );
741	  }
742	  if (reasons.length > 0) return { status: 'amber', reasons };
743	
744	  return { status: 'ok', reasons: [] };
745	}
