747	/** Entrada de {@link buildNoMovementException}. */
748	export interface NoMovementExceptionInput {
749	  lojaId: number;
750	  lojaNome: string;
751	  /** Timestamp da última movimentação (ISO/Date), ou null se nenhuma hoje. */
752	  lastMovementAt: Date | string | null;
753	  now: Date;
754	  /** Janela de funcionamento (default lojas; fábrica usa TV_FACTORY_HOURS). */
755	  hours?: TvBusinessHours;
756	  /** Threshold em horas (default lojas 3h; fábrica 2h). */
757	  thresholdHours?: number;
758	}
