760	/**
761	 * Exceção "sem movimentação" derivada DIRETO do dado estruturado (timestamp
762	 * da última bipagem + janela), nunca por parsing de string de ragReasons —
763	 * por isso INDEPENDE da cor do card (aparece mesmo com card vermelho) e
764	 * cobre também a fábrica (janela/threshold próprios via parâmetros).
765	 * Retorna null quando não há gap acima do threshold dentro da janela.
766	 */
767	export function buildNoMovementException(
768	  input: NoMovementExceptionInput,
769	): TvException | null {
770	  const threshold = input.thresholdHours ?? NO_MOVEMENT_THRESHOLD_HOURS;
771	  const gap = hoursWithoutMovementInWindow(
772	    input.lastMovementAt,
773	    input.now,
774	    input.hours ?? TV_BUSINESS_HOURS,
775	  );
776	  if (gap === null || gap <= threshold) return null;
777	  return {
778	    id: `no-movement:${input.lojaId}`,
779	    kind: 'no-movement',
780	    severity: 'amber',
781	    lojaId: input.lojaId,
782	    lojaNome: input.lojaNome,
783	    message: `${input.lojaNome} sem movimentação há ${Math.floor(gap)}h em horário comercial`,
784	  };
785	}
