787	// ─────────────────────────────────────────────────────────────────────────────
788	// Formatação compacta de moeda (tipografia de TV: "R$ 12,4k")
789	// ─────────────────────────────────────────────────────────────────────────────
790	
791	function trimOneDecimal(v: number): string {
792	  const rounded = Math.round(v * 10) / 10;
793	  return rounded.toLocaleString('pt-BR', {
794	    minimumFractionDigits: 0,
795	    maximumFractionDigits: 1,
796	  });
797	}
798	
799	/**
800	 * Formata um valor em BRL compacto para leitura a 3-5 metros:
801	 * 950 → "R$ 950" · 12.400 → "R$ 12,4k" · 1.250.000 → "R$ 1,3M".
802	 * Valores negativos preservam o sinal ("-R$ 1,2k").
803	 */
804	export function formatCompactBRL(value: number): string {
805	  const sign = value < 0 ? '-' : '';
806	  const abs = Math.abs(value);
807	  // Bump pra M quando o arredondamento em k chegaria a 1000k
808	  if (abs >= 1_000_000 || (abs >= 1_000 && Math.round(abs / 100) >= 10_000)) {
809	    return `${sign}R$ ${trimOneDecimal(abs / 1_000_000)}M`;
810	  }
811	  if (abs >= 1_000) {
812	    return `${sign}R$ ${trimOneDecimal(abs / 1_000)}k`;
813	  }
814	  return `${sign}R$ ${Math.round(abs).toLocaleString('pt-BR')}`;
815	}
816	
817	// ─────────────────────────────────────────────────────────────────────────────
818	// Staleness
819	// ─────────────────────────────────────────────────────────────────────────────
820	
821	/**
822	 * Classifica o frescor de um dado-fonte dado o intervalo esperado:
823	 * - `fresh`: idade abaixo de 2× o intervalo esperado (tolera um ciclo perdido).
824	 * - `stale`: idade entre 2× e 6× (âmbar na UI, conforme spec).
825	 * - `very-stale`: idade a partir de 6×, timestamp inválido ou ausente.
826	 */
827	export function classifyStaleness(
828	  lastUpdatedAt: Date | string | number | null | undefined,
829	  expectedIntervalMs: number,
830	  now: Date,
831	): TvFreshnessLevel {
832	  if (lastUpdatedAt == null) return 'very-stale';
833	  const ts = new Date(lastUpdatedAt).getTime();
834	  if (!Number.isFinite(ts) || ts <= 0) return 'very-stale';
835	  const age = now.getTime() - ts;
836	  if (age < 2 * expectedIntervalMs) return 'fresh';
837	  if (age < 6 * expectedIntervalMs) return 'stale';
838	  return 'very-stale';
839	}
840	
841	/**
842	 * Monta o freshness consolidado a partir dos timestamps CRUS de última
843	 * atualização bem-sucedida (React Query `dataUpdatedAt`, em ms; 0 = nunca).
844	 *
845	 * A classificação depende de `now`: o chamador DEVE reavaliar com um relógio
846	 * que AVANÇA (tick de minuto), para que um outage total — nenhuma query
847	 * devolvendo dado novo — escale o chip pra âmbar quando `dataUpdatedAt`
848	 * parar de avançar além de 2× o intervalo esperado.
849	 */
850	export function buildFreshness(
851	  liveUpdatedAtMs: number,
852	  stockUpdatedAtMs: number,
853	  intervals: { liveMs: number; slowMs: number },
854	  now: Date,
855	): TvFreshness {
856	  const liveUpdatedAt =
857	    liveUpdatedAtMs > 0 ? new Date(liveUpdatedAtMs).toISOString() : null;
858	  const stockUpdatedAt =
859	    stockUpdatedAtMs > 0 ? new Date(stockUpdatedAtMs).toISOString() : null;
860	  return {
861	    vendasLive: {
862	      updatedAt: liveUpdatedAt,
863	      level: classifyStaleness(liveUpdatedAt, intervals.liveMs, now),
864	      expectedIntervalMs: intervals.liveMs,
865	    },
866	    estoque: {
867	      updatedAt: stockUpdatedAt,
868	      level: classifyStaleness(stockUpdatedAt, intervals.slowMs, now),
869	      expectedIntervalMs: intervals.slowMs,
870	    },
871	    geradoEm: now.toISOString(),
872	  };
873	}
