875	// ─────────────────────────────────────────────────────────────────────────────
876	// Exceções — ordenação e corte
877	// ─────────────────────────────────────────────────────────────────────────────
878	
879	const SEVERITY_ORDER: Record<string, number> = { red: 0, amber: 1 };
880	// design.md §6.1: rupturas → abaixo-do-mínimo → sem-bipagem → stale
881	const KIND_ORDER: Record<string, number> = {
882	  'stock-out': 0,
883	  'stock-low': 1,
884	  'no-movement': 2,
885	  'stale-data': 3,
886	};
887	
888	/**
889	 * Ordena exceções por severidade (vermelho antes de âmbar), depois por tipo
890	 * (falta total, abaixo do mínimo, sem movimentação, dado stale — nesta ordem,
891	 * design.md §6.1) e por mensagem (estável), limitando a `limit` linhas com
892	 * contagem do excedente.
893	 */
894	export function sortAndLimitExceptions(
895	  exceptions: TvException[],
896	  limit: number = TV_EXCEPTIONS_LIMIT,
897	): TvExceptionsResult {
898	  const sorted = [...exceptions].sort((a, b) => {
899	    const sev = (SEVERITY_ORDER[a.severity] ?? 9) - (SEVERITY_ORDER[b.severity] ?? 9);
900	    if (sev !== 0) return sev;
901	    const kind = (KIND_ORDER[a.kind] ?? 9) - (KIND_ORDER[b.kind] ?? 9);
902	    if (kind !== 0) return kind;
903	    return a.message.localeCompare(b.message, 'pt-BR');
904	  });
905	  return {
906	    items: sorted.slice(0, limit),
907	    overflowCount: Math.max(0, sorted.length - limit),
908	    totalCount: sorted.length,
909	  };
910	}
