916	/** Linha mínima de `movimentacoes` necessária à agregação. */
917	export interface MovementRow {
918	  loja_id: number | null;
919	  tipo_movimentacao: string;
920	  data_movimentacao: string | null;
921	}
922	
923	/** Resultado por loja da agregação de movimentações do dia. */
924	export interface MovementAggregate {
925	  entradas: number;
926	  saidas: number;
927	  ultimaBipagem: string | null;
928	}
929	
930	/**
931	 * Agrega movimentações do dia por loja: contagem de entradas, saídas e
932	 * timestamp da última movimentação ("última bipagem"). Linhas sem loja
933	 * são ignoradas.
934	 */
935	export function aggregateMovements(
936	  rows: MovementRow[],
937	): Map<number, MovementAggregate> {
938	  const out = new Map<number, MovementAggregate>();
939	  for (const row of rows) {
940	    if (row.loja_id == null) continue;
941	    let agg = out.get(row.loja_id);
942	    if (!agg) {
943	      agg = { entradas: 0, saidas: 0, ultimaBipagem: null };
944	      out.set(row.loja_id, agg);
945	    }
946	    if (row.tipo_movimentacao === 'entrada') agg.entradas += 1;
947	    else if (row.tipo_movimentacao === 'saida') agg.saidas += 1;
948	    if (
949	      row.data_movimentacao &&
950	      (agg.ultimaBipagem === null || row.data_movimentacao > agg.ultimaBipagem)
951	    ) {
952	      agg.ultimaBipagem = row.data_movimentacao;
953	    }
954	  }
955	  return out;
956	}
