958	/**
959	 * Normaliza um valor de `produtos_master.setor` para comparação: trim,
960	 * minúsculas e remoção de acentos (NFD). O banco tem caixa/acentuação
961	 * inconsistentes no MESMO setor (ex.: "CÂMARA FRIA" e "Câmara Fria") —
962	 * toda comparação de setor DEVE passar por aqui.
963	 */
964	export function normalizeSetor(value: string | null | undefined): string {
965	  return (value ?? '')
966	    .normalize('NFD')
967	    .replace(/\p{M}/gu, '')
968	    .trim()
969	    .toLowerCase();
970	}
971	
972	/**
973	 * true quando o setor é o {@link TV_ALERT_SETOR} (igualdade EXATA após
974	 * {@link normalizeSetor} — nunca prefixo: "PRODUTOS DE LIMPEZA" NÃO conta).
975	 */
976	export function isTvAlertSetor(setor: string | null | undefined): boolean {
977	  return normalizeSetor(setor) === normalizeSetor(TV_ALERT_SETOR);
978	}
