997	/**
998	 * Classifica linhas de estoque em alertas por loja (apenas produtos ATIVOS
999	 * devem chegar aqui — o JOIN com `produtos_master.ativo = true` é feito na
1000	 * query). Regras (critério existente do projeto, sem schema novo):
1001	 * - SÓ setor {@link TV_ALERT_SETOR} entra em alerta (regra do CTO
1002	 *   2026-06-05: alertas só do setor de produtos vendáveis) — comparação
1003	 *   normalizada client-side porque a caixa no banco é inconsistente;
1004	 * - zerado (vermelho): quantidade ≤ 0 com mínimo definido (positivo);
1005	 * - abaixo do mínimo (âmbar): quantidade entre 0 exclusivo e o mínimo.
1006	 */
1007	export function buildStockSummary(rows: StockRow[]): Map<number, StockDetail> {
1008	  const out = new Map<number, StockDetail>();
1009	  for (const row of rows) {
1010	    if (row.loja_id == null) continue;
1011	    if (!isTvAlertSetor(row.setor)) continue; // fora do setor vendável → sem alerta
