1091	  knownDegustLojaIds: ReadonlySet<number>,
1092	): FlashRow[] {
1093	  const out: FlashRow[] = [];
1094	  for (const row of rows) {
1095	    if (knownDegustLojaIds.has(row.loja_id)) {
1096	      out.push(row);
1097	      continue;
1098	    }
1099	    const mapped = degustCodeToLoja.get(row.loja_id);
1100	    if (mapped != null) {
1101	      out.push({ ...row, loja_id: mapped });
1102	    }
1103	    // não mapeável → descartado de propósito (ver TSDoc)
