1108	/**
1109	 * Converte os itens de alerta de uma unidade em estoque crítico NOMEADO,
1110	 * ordenado por severidade: zerados (⛔) primeiro, depois abaixo do mínimo
1111	 * (⚠) por % FALTANTE decrescente ((minima − quantidade) / minima); empate
1112	 * por nome (estável). Dentro dos zerados, quantidade mais negativa primeiro
1113	 * (mesma fração). A coluna exibe os {@link TV_CRITICAL_TOP_N} primeiros;
1114	 * o drill-down, a lista completa.
1115	 */
1116	export function sortCriticalItems(items: TvStockAlertItem[]): TvCriticalItem[] {
1117	  const missingFraction = (c: TvCriticalItem): number =>
1118	    c.minima > 0 ? (c.minima - c.quantidade) / c.minima : 0;
1119	  return items
1120	    .map<TvCriticalItem>((i) => ({
1121	      nome: i.produtoNome,
1122	      quantidade: i.quantidade,
1123	      minima: i.quantidadeMinima,
1124	      severity: i.zerado ? 'zerado' : 'abaixo-minimo',
1125	    }))
1126	    .sort((a, b) => {
1127	      if (a.severity !== b.severity) return a.severity === 'zerado' ? -1 : 1;
1128	      const diff = missingFraction(b) - missingFraction(a);
1129	      if (diff !== 0) return diff;
1130	      return a.nome.localeCompare(b.nome, 'pt-BR');
1131	    });
1132	}
