1267	/** Página de resultado mínima consumida por {@link fetchAllPages}. */
1268	export interface TvPageResult<T> {
1269	  data: T[] | null;
1270	  error: { message: string } | null;
1271	}
1272	
1273	/**
1274	 * Busca TODAS as linhas paginando com `.range()`: o PostgREST corta qualquer
1275	 * resposta em 1000 linhas mesmo com `.limit()` maior — truncamento SILENCIOSO
1276	 * (mesmo padrão de `features/producao/hooks/useProductionForecast`).
1277	 *
1278	 * Loop até a página vir menor que `pageSize`. O fetcher é injetado (esta
1279	 * função não faz I/O próprio — testável com mock) e DEVE aplicar ordenação
1280	 * estável (`.order` em coluna única, ex.: `id`) para as páginas não se
1281	 * sobreporem entre requests.
1282	 */
1283	export async function fetchAllPages<T>(
1284	  fetchPage: (from: number, to: number) => PromiseLike<TvPageResult<T>>,
1285	  pageSize = 1000,
1286	): Promise<T[]> {
1287	  const all: T[] = [];
1288	  let offset = 0;
1289	  for (;;) {
1290	    const { data, error } = await fetchPage(offset, offset + pageSize - 1);
1291	    if (error) throw error;
1292	    const rows = data ?? [];
1293	    all.push(...rows);
1294	    if (rows.length < pageSize) return all;
1295	    offset += pageSize;
1296	  }
1297	}
