/**
 * Janela de funcionamento das LOJAS usada no pró-rata da meta (hora local,
 * design.md §1.6 regra 5: 10:00–22:00). AJUSTÁVEL: se o horário comercial
 * mudar, basta alterar aqui — pró-rata e "sem movimentação" derivam daqui.
 */
export const TV_BUSINESS_HOURS: TvBusinessHours = { start: 10, end: 22 };

/** Soma `days` dias a uma data, retornando nova instância. */
export function addDays(d: Date, days: number): Date {
  const out = new Date(d);
  out.setDate(out.getDate() + days);
  return out;
}

