/** Soma `days` dias a uma data, retornando nova instância. */
export function addDays(d: Date, days: number): Date {
  const out = new Date(d);
  out.setDate(out.getDate() + days);
  return out;
}

/**
 * Dia COMERCIAL corrente do painel (YYYY-MM-DD local).
 *
 * O dia comercial vai de 08h a 23h ({@link TV_BUSINESS_HOURS}): a partir
 * das 23h o painel VIRA para o dia seguinte — tudo zera e o novo dia
 * começa — então `now` com hora ≥ 23 retorna AMANHÃ. Vendas de madrugada
 * (00h–05h) pertencem ao caixa do dia ANTERIOR (mesma convenção de
 * {@link TV_OVERNIGHT_END_HOUR}/{@link businessHourRank}): nesse horário o
 * dia comercial corrente é o próprio dia-calendário, ainda zerado até a
 * abertura das 08h — os totais do dia fechado ficam acessíveis no
 * histórico (◀).
 */
export function businessTodayIso(now: Date): string {
  return now.getHours() >= TV_BUSINESS_HOURS.end
    ? toIsoDateLocal(addDays(now, 1))
    : toIsoDateLocal(now);
}

