describe('businessTodayIso (virada do dia comercial às 23h)', () => {
  it('antes das 23h retorna o próprio dia-calendário', () => {
    expect(businessTodayIso(at(12))).toBe('2026-06-04');
    expect(businessTodayIso(at(22, 59))).toBe('2026-06-04');
  });

  it('a partir das 23h vira pro dia SEGUINTE (painel zera)', () => {
    expect(businessTodayIso(at(23))).toBe('2026-06-05');
    expect(businessTodayIso(at(23, 59))).toBe('2026-06-05');
  });

  it('madrugada (00–05h) é o dia-calendário corrente — caixa de ontem fica no histórico', () => {
    expect(businessTodayIso(new Date(2026, 5, 5, 2, 0, 0))).toBe('2026-06-05');
    expect(businessTodayIso(new Date(2026, 5, 5, 0, 0, 0))).toBe('2026-06-05');
  });

  it('virada de mês: 23h do último dia já é o dia 1º seguinte', () => {
    expect(businessTodayIso(new Date(2026, 5, 30, 23, 15, 0))).toBe('2026-07-01');
  });
});

describe('fallback do delta intradiário NUNCA usa o dia inteiro cru (caso Asa Sul 10:58)', () => {
  // Cenário real do CTO (2026-06-11): flash R$ 643,20 às 10:58; ontem fechou
  // em R$ 10.032,88. Comparar com o dia INTEIRO de ontem mostrava −95% no
  // painel quando o honesto (curva real) era ≈ +82%.
  const NOW = new Date(2026, 5, 11, 10, 58, 0);
  const PREV_TOTAL = 10_032.88;
  const FLASH = 643.2;

  it('sem curva horária: base = pró-rata linear da janela 8-23, não o total cheio', () => {
    const paceBase = hourlyPaceBase(PREV_TOTAL, undefined, NOW);
    expect(paceBase).toBeNull(); // sem curva → caller cai no pró-rata
    const base = paceBase ?? proRataDayBase(PREV_TOTAL, NOW);
    // 10:58 → fração (10,9667 − 8)/15 ≈ 0,1978 → base ≈ R$ 1.984
    expect(base).toBeCloseTo(PREV_TOTAL * ((10 + 58 / 60 - 8) / 15), 2);
    const delta = relativeDelta(FLASH, base);
    // Delta honesto ≈ −68% — nunca o −94% do dia inteiro cru
    expect(delta).toBeGreaterThan(-70);
    expect(delta).not.toBeCloseTo(relativeDelta(FLASH, PREV_TOTAL) ?? 0, 0);
  });

  it('pró-rata null fora da janela → delta null (sem base inventada)', () => {
    const dawn = new Date(2026, 5, 11, 7, 0, 0);
    const base =
      hourlyPaceBase(PREV_TOTAL, undefined, dawn) ??
      proRataDayBase(PREV_TOTAL, dawn);
    expect(base).toBeNull();
    expect(relativeDelta(FLASH, base)).toBeNull();
  });

  it('com curva horária continua usando o pace REAL (delta ≈ +82%)', () => {
    // Curva de ontem: R$ 366 no bucket "10"; o resto do dia vem depois.
    const curve: Record<string, number> = { '10': 366, '12': 9_666.88 };
    const paceBase = hourlyPaceBase(PREV_TOTAL, curve, NOW);
    // Às 10:58 só o bucket "10" entrou (58/60 da hora): ≈ R$ 353,80
    expect(paceBase).toBeCloseTo(366 * (58 / 60), 1);
    const delta = relativeDelta(
      FLASH,
      paceBase ?? proRataDayBase(PREV_TOTAL, NOW),
    );
    expect(delta).toBeCloseTo(81.8, 0);
  });
});

